//! GitHub Actions output formatter.
//!
//! Emits workflow commands (`::error::`, `::warning::`, `::notice::`) that
//! GitHub Actions renders as inline annotations on pull requests and in
//! the Actions log.

use super::LintFormatter;
use crate::lint::{LintDiagnostic, Severity};
use std::io::Write;

/// Formats lint output as GitHub Actions workflow commands.
pub struct GithubActionsFormatter;

impl GithubActionsFormatter {
    /// Create a new GitHub Actions formatter.
    pub fn new() -> Self {
        Self
    }

    fn severity_command(severity: Severity) -> &'static str {
        match severity {
            Severity::Error => "error",
            Severity::Warning => "warning",
            Severity::Hint => "notice",
        }
    }
}

impl Default for GithubActionsFormatter {
    fn default() -> Self {
        Self::new()
    }
}

impl LintFormatter for GithubActionsFormatter {
    fn format<W: Write>(
        &self,
        diagnostics: &[LintDiagnostic],
        writer: &mut W,
    ) -> std::io::Result<()> {
        for diag in diagnostics {
            let cmd = Self::severity_command(diag.severity);

            // Build the optional parameters string
            let mut params = Vec::new();

            if let Some(ref span) = diag.span {
                params.push(format!("file={}", span.file.display()));
                params.push(format!("line={}", span.start_line));
                if span.start_col > 1 {
                    params.push(format!("col={}", span.start_col));
                }
                if span.end_line != span.start_line {
                    params.push(format!("endLine={}", span.end_line));
                }
            }

            params.push(format!("title={}", diag.rule_id.0));

            let params_str = params.join(",");

            writeln!(writer, "::{cmd} {params_str}::{}", diag.message)?;
        }

        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::lint::{RuleId, Span};

    #[test]
    fn formats_error_annotation() {
        let formatter = GithubActionsFormatter::new();
        let diagnostics = vec![LintDiagnostic::new(
            RuleId::new("test-rule"),
            Severity::Error,
            "Something went wrong",
        )
        .with_span(Span::line("config.yml", 10))];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert_eq!(
            output.trim(),
            "::error file=config.yml,line=10,title=test-rule::Something went wrong"
        );
    }

    #[test]
    fn formats_warning_annotation() {
        let formatter = GithubActionsFormatter::new();
        let diagnostics = vec![LintDiagnostic::new(
            RuleId::new("app-name"),
            Severity::Warning,
            "App name has spaces",
        )];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert!(output.starts_with("::warning "));
        assert!(output.contains("title=app-name"));
        assert!(output.contains("::App name has spaces"));
    }

    #[test]
    fn formats_hint_as_notice() {
        let formatter = GithubActionsFormatter::new();
        let diagnostics = vec![LintDiagnostic::new(
            RuleId::new("info-rule"),
            Severity::Hint,
            "Consider this",
        )];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert!(output.starts_with("::notice "));
    }

    #[test]
    fn includes_column_when_not_one() {
        let formatter = GithubActionsFormatter::new();
        let diagnostics = vec![
            LintDiagnostic::new(RuleId::new("test"), Severity::Error, "msg")
                .with_span(Span::new("config.yml", 10, 5, 10, 20)),
        ];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert!(output.contains("col=5"));
    }

    #[test]
    fn omits_column_when_one() {
        let formatter = GithubActionsFormatter::new();
        let diagnostics = vec![
            LintDiagnostic::new(RuleId::new("test"), Severity::Error, "msg")
                .with_span(Span::line("config.yml", 10)),
        ];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert!(!output.contains("col="));
    }

    #[test]
    fn includes_end_line_for_multiline_span() {
        let formatter = GithubActionsFormatter::new();
        let diagnostics = vec![
            LintDiagnostic::new(RuleId::new("test"), Severity::Error, "msg")
                .with_span(Span::new("config.yml", 10, 1, 15, 1)),
        ];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert!(output.contains("endLine=15"));
    }

    #[test]
    fn handles_no_span() {
        let formatter = GithubActionsFormatter::new();
        let diagnostics = vec![LintDiagnostic::new(
            RuleId::new("test"),
            Severity::Error,
            "No location",
        )];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert_eq!(output.trim(), "::error title=test::No location");
    }

    #[test]
    fn formats_multiple_diagnostics() {
        let formatter = GithubActionsFormatter::new();
        let diagnostics = vec![
            LintDiagnostic::new(RuleId::new("r1"), Severity::Error, "err"),
            LintDiagnostic::new(RuleId::new("r2"), Severity::Warning, "warn"),
        ];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        let lines: Vec<_> = output.lines().collect();
        assert_eq!(lines.len(), 2);
        assert!(lines[0].starts_with("::error "));
        assert!(lines[1].starts_with("::warning "));
    }

    #[test]
    fn empty_diagnostics_produces_no_output() {
        let formatter = GithubActionsFormatter::new();
        let diagnostics: Vec<LintDiagnostic> = vec![];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();

        assert!(output.is_empty());
    }

    #[test]
    fn default_impl_works() {
        let _formatter = GithubActionsFormatter::default();
    }
}

